#include "routing_search.hpp"
#include <fstream>
#include <iostream>
#include <iomanip>
struct Edge{int from,to,dx,dy,cost;};struct Point{double x,y;};struct Constraint{int x,y,cost;};
int main(int argc,char**argv){try{
 if(argc!=2)throw std::runtime_error("Expected JSON output");std::array<int,496>input,out;input.fill(-1);out.fill(-1);unsigned n=0;for(unsigned i=0;i<std::size(archdata::NETS);++i){auto net=archdata::NETS[i];if(input[net.to]<0)input[net.to]=n++;out[net.from]=i;}if(n!=160)throw std::runtime_error("Unexpected core count");std::vector<Edge>edges;for(auto a:archdata::ARCS)if(input[a.from]>=0 && out[a.to]>=0){auto net=archdata::NETS[out[a.to]];auto v=archdata::VECTORS[net.vector];edges.push_back({input[a.from],input[net.to],v.x,v.y,int(a.delay+net.delay)});}
 std::vector<Point>poly={{-20,-20},{20,-20},{20,20},{-20,20}};std::vector<Constraint>constraints;
 auto feasible=[&](Point p,Constraint&c){std::array<double,160>d{};std::array<int,160>parent;parent.fill(-1);int last=-1;for(unsigned iteration=0;iteration<n;++iteration){last=-1;for(unsigned j=0;j<edges.size();++j){auto e=edges[j];double value=d[e.from]+e.cost-p.x*e.dx-p.y*e.dy;if(d[e.to]>value+1e-8){d[e.to]=value;parent[e.to]=j;last=e.to;}}if(last<0)return true;}for(unsigned i=0;i<n;++i){if(parent[last]<0)throw std::runtime_error("Missing negative-cycle parent");last=edges[parent[last]].from;}int start=last;c={0,0,0};unsigned steps=0;do{auto e=edges[parent[last]];c.x+=e.dx;c.y+=e.dy;c.cost+=e.cost;last=e.from;if(++steps>n)throw std::runtime_error("Cycle extraction failed");}while(last!=start);if(!c.x && !c.y)throw std::runtime_error("Zero-displacement negative cycle");return false;};
 for(unsigned iteration=0;;++iteration){if(iteration>1000 || poly.empty())throw std::runtime_error("Potential polygon did not converge");bool done=true;for(auto p:poly){Constraint c;if(feasible(p,c))continue;done=false;constraints.push_back(c);std::vector<Point>clipped;for(unsigned j=0;j<poly.size();++j){auto a=poly[j],b=poly[(j+1)%poly.size()];double va=c.x*a.x+c.y*a.y-c.cost,vb=c.x*b.x+c.y*b.y-c.cost;bool ia=va<=1e-9,ib=vb<=1e-9;if(ia)clipped.push_back(a);if(ia!=ib){double t=va/(va-vb);clipped.push_back({a.x+t*(b.x-a.x),a.y+t*(b.y-a.y)});}}poly=std::move(clipped);break;}if(done)break;}
 std::ofstream f(argv[1]);f<<std::setprecision(17)<<"{\"architecture_only\":true,\"wall_skip_edges\":false,\"inputs\":"<<n<<",\"edges\":"<<edges.size()<<",\"vertices\":[";for(unsigned i=0;i<poly.size();++i){if(i)f<<',';f<<'['<<poly[i].x<<','<<poly[i].y<<']';}f<<"],\"cycle_constraints\":[";for(unsigned i=0;i<constraints.size();++i){if(i)f<<',';auto c=constraints[i];f<<'['<<c.x<<','<<c.y<<','<<c.cost<<']';}f<<"]}\n";if(!f)throw std::runtime_error("Write failed");std::cerr<<"vertices="<<poly.size()<<" constraints="<<constraints.size()<<'\n';
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
